    """Check if a file is a valid CSV."""
    check_name = "csv_valid"
    passed = False
    message = ""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            row_count = 0
            for i, row in enumerate(reader):
                row_count += 1
                # Check if row is not empty and has at least one value
                if len(row) == 0:
                    message = f"CSV {os.path.basename(filepath)} has empty rows"
                    passed = False
                    break
            if passed:
                message = f"CSV {os.path.basename(filepath)} has {row_count} rows"
    except Exception as e:
        message = f"CSV {os.path.basename(filepath)} failed to parse: {str(e)}"
        passed = False
    return {
        "check_name": check_name,
        "passed": passed,
        "message": message
    }

